//! Colour palette, optionally generated by matugen into `~/.config/rmp/colors.json`.
use crate::config::Config;
use serde::Deserialize;
use std::path::Path;

#[derive(Clone, Debug)]
pub struct Theme {
    pub accent: [u8; 3],
    pub secondary: [u8; 3],
    pub surface: [u8; 3],
    pub surface_hi: [u8; 3],
    pub background: [u8; 3],
    pub on_surface: [u8; 3],
    pub dim: [u8; 3],
    pub outline: [u8; 3],
    pub error: [u8; 3],
}

#[derive(Deserialize, Default)]
struct PaletteFile {
    accent: Option<String>,
    secondary: Option<String>,
    surface: Option<String>,
    surface_hi: Option<String>,
    background: Option<String>,
    on_surface: Option<String>,
    on_surface_variant: Option<String>,
    outline: Option<String>,
    error: Option<String>,
}

impl Theme {
    pub fn builtin(accent: [u8; 3]) -> Self {
        Self {
            accent,
            secondary: [215, 224, 232],
            surface: [22, 30, 40],
            surface_hi: [38, 52, 64],
            background: [14, 20, 28],
            on_surface: [225, 232, 238],
            dim: [125, 138, 150],
            outline: [75, 92, 108],
            error: [230, 110, 110],
        }
    }

    pub fn load(cfg: &Config) -> Self {
        let mut theme = Self::builtin(cfg.accent);
        if cfg.theme == "builtin" {
            return theme;
        }
        theme.apply_file(&crate::matugen::colors_path());
        theme
    }

    fn apply_file(&mut self, path: &Path) {
        let Ok(text) = std::fs::read_to_string(path) else {
            return;
        };
        let Ok(p) = serde_json::from_str::<PaletteFile>(&text) else {
            return;
        };
        let set = |slot: &mut [u8; 3], v: &Option<String>| {
            if let Some(c) = v.as_deref().and_then(parse_hex) {
                *slot = c;
            }
        };
        set(&mut self.accent, &p.accent);
        set(&mut self.secondary, &p.secondary);
        set(&mut self.surface, &p.surface);
        set(&mut self.surface_hi, &p.surface_hi);
        set(&mut self.background, &p.background);
        set(&mut self.on_surface, &p.on_surface);
        set(&mut self.dim, &p.on_surface_variant);
        set(&mut self.outline, &p.outline);
        set(&mut self.error, &p.error);
    }
}

pub fn parse_hex(s: &str) -> Option<[u8; 3]> {
    let s = s.trim().trim_start_matches('#');
    if s.len() != 6 {
        return None;
    }
    Some([
        u8::from_str_radix(&s[0..2], 16).ok()?,
        u8::from_str_radix(&s[2..4], 16).ok()?,
        u8::from_str_radix(&s[4..6], 16).ok()?,
    ])
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_hex_with_and_without_hash() {
        assert_eq!(parse_hex("#7fd6be"), Some([127, 214, 190]));
        assert_eq!(parse_hex("7fd6be"), Some([127, 214, 190]));
        assert_eq!(parse_hex("#fff"), None);
        assert_eq!(parse_hex("#gggggg"), None);
    }

    #[test]
    fn builtin_theme_keeps_accent() {
        let t = Theme::builtin([1, 2, 3]);
        assert_eq!(t.accent, [1, 2, 3]);
        assert_ne!(t.dim, t.outline);
    }
}
